import { z } from "zod";

// Messages are translation keys; render them with t(errors.<field>.message).
export const developerSchema = z.object({
  name: z.string().min(1, "developers.validation.nameRequired"),
  email: z.string().email("developers.validation.invalidEmail"),
  phone_number: z.string().min(1, "developers.validation.phoneRequired"),
  website: z.string().min(1, "developers.validation.websiteRequired").url("developers.validation.invalidUrl"),
  logo: z.any().optional(),
  description: z.string().min(1, "developers.validation.descriptionRequired"),
  status: z.string().optional(),
  is_top: z.boolean(),
  country_id: z.string().optional(),
  slug: z.string().optional(),
  meta_title: z.string().optional(),
  meta_description: z.string().optional(),
  sync_erp_next: z.boolean().optional(),
  admin_password: z.string().optional(),
}).superRefine((data, ctx) => {
  // Mirrors the backend rule: admin_password is required when creating an
  // ERPNext tenant, and must satisfy Password::min(8)->letters()->mixedCase()->numbers().
  if (!data.sync_erp_next) return;

  const password = data.admin_password ?? "";
  const issue = (message: string) =>
    ctx.addIssue({ code: "custom", path: ["admin_password"], message });

  if (!password) return issue("developers.validation.adminPasswordRequired");
  if (password.length < 8) return issue("developers.validation.adminPasswordMin");
  if (!/[a-z]/.test(password) || !/[A-Z]/.test(password))
    return issue("developers.validation.adminPasswordMixedCase");
  if (!/\d/.test(password)) return issue("developers.validation.adminPasswordNumber");
});

export type FormValues = z.infer<typeof developerSchema>;
